<!DOCTYPE html>
<html lang="pt-BR">
<head>
<meta charset="UTF-8">
<title>Diario Official do Estado de São Paulo</title>
<style>
    body {
        font-family: 'Times New Roman', Times, serif;
        max-width: 1200px;
        margin: 0 auto;
        padding: 20px;
        background-color: #f4f1e9;
        color: #1a1a1a;
    }
    .header {
        text-align: center;
        border-bottom: 3px solid black;
        padding-bottom: 10px;
        margin-bottom: 10px;
    }
    .header h1 {
        font-size: 24px;
        letter-spacing: 2px;
        margin: 5px 0;
        font-weight: bold;
    }
    .header h2 {
        font-size: 60px;
        margin: 0;
        letter-spacing: 3px;
        font-family: Georgia, serif;
        font-weight: 900;
    }
    .header h3 {
        font-size: 28px;
        margin: 5px 0;
        letter-spacing: 1px;
    }
    .info-bar {
        display: flex;
        justify-content: space-between;
        border-bottom: 2px solid black;
        padding: 5px 0;
        margin-bottom: 20px;
        font-size: 14px;
        font-weight: bold;
    }
    .columns {
        display: flex;
        justify-content: space-between;
        gap: 20px;
    }
    .column {
        flex: 1;
        text-align: justify;
        font-size: 13px;
        line-height: 1.3;
        border-right: 1px solid #ccc;
        padding-right: 15px;
    }
    .column:last-child {
        border-right: none;
    }
    .section-title {
        text-align: center;
        font-weight: bold;
        font-size: 15px;
        margin: 10px 0 5px 0;
    }
    .subsection-title {
        text-align: center;
        font-style: italic;
        margin: 5px 0;
    }
    h4 {
        text-align: center;
        margin: 8px 0 4px 0;
        font-size: 13px;
    }
    p {
        margin: 4px 0;
    }
    .day-title {
        text-align: center;
        font-style: italic;
        margin: 8px 0 4px 0;
    }
</style>
